import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/marketing/waitlist/conversion
 *
 * Returns conversion stats for the current studio's waitlist.
 * Gated behind marketing_basic (Studio+).
 */
export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const studioId = authUser.studioId

    const now = new Date()
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString()
    const sixtyDaysAgo = new Date(now.getTime() - 60 * 24 * 60 * 60 * 1000).toISOString()

    // Current 30d window
    const [joinedRes, convertedRes, priorJoinedRes, priorConvertedRes] = await Promise.all([
      supabase
        .from('waitlist_entries')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gte('created_at', thirtyDaysAgo),
      supabase
        .from('waitlist_entries')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .eq('status', 'booked')
        .gte('created_at', thirtyDaysAgo),
      // Prior 30d window (30-60 days ago)
      supabase
        .from('waitlist_entries')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gte('created_at', sixtyDaysAgo)
        .lt('created_at', thirtyDaysAgo),
      supabase
        .from('waitlist_entries')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .eq('status', 'booked')
        .gte('created_at', sixtyDaysAgo)
        .lt('created_at', thirtyDaysAgo),
    ])

    const joined30d = joinedRes.count ?? 0
    const converted30d = convertedRes.count ?? 0
    const priorJoined = priorJoinedRes.count ?? 0
    const priorConverted = priorConvertedRes.count ?? 0

    const conversion_rate = joined30d > 0 ? (converted30d / joined30d) * 100 : 0
    const prior_period_rate = priorJoined > 0 ? (priorConverted / priorJoined) * 100 : 0
    const delta_pct = prior_period_rate > 0
      ? ((conversion_rate - prior_period_rate) / prior_period_rate) * 100
      : null

    return NextResponse.json({
      data: {
        joined_30d: joined30d,
        converted_30d: converted30d,
        conversion_rate: Math.round(conversion_rate * 10) / 10,
        prior_period_rate: Math.round(prior_period_rate * 10) / 10,
        delta_pct: delta_pct !== null ? Math.round(delta_pct * 10) / 10 : null,
      },
    })
  } catch (err) {
    logger.error({ err }, 'waitlist conversion stats failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

/**
 * GET  /api/marketing/waitlist/auto-promote-rules
 * PATCH /api/marketing/waitlist/auto-promote-rules
 *
 * Reads/upserts the studio's auto-promote rules for waitlist entries.
 * The marketing_waitlist_rules table is studio-scoped (one row per studio).
 *
 * Gated: owner/admin only, marketing_basic.
 */

const RulesSchema = z.object({
  auto_promote_on_cancel: z.boolean(),
  auto_promote_window_minutes: z.number().int().min(0).max(1440).default(5),
  min_lead_time_hours: z.number().int().min(0).max(168).default(24),
  notify_via: z.array(z.enum(['email', 'sms'])).min(1),
  template_subject: z.string().min(1).max(200),
  template_body: z.string().min(1).max(2000),
})

const DEFAULT_RULES = {
  auto_promote_on_cancel: false,
  auto_promote_window_minutes: 5,
  min_lead_time_hours: 24,
  notify_via: ['email'] as string[],
  template_subject: 'A spot just opened',
  template_body: 'A slot just opened: {{slot}}. Reply YES to claim it — this offer expires in 24 hours.',
}

export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('marketing_waitlist_rules')
      .select('*')
      .eq('studio_id', authUser.studioId)
      .maybeSingle()

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'waitlist rules fetch failed')
      return NextResponse.json({ error: 'Failed to fetch rules' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? { ...DEFAULT_RULES, studio_id: authUser.studioId } })
  } catch (err) {
    logger.error({ err }, 'waitlist rules GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = RulesSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('marketing_waitlist_rules')
      .upsert(
        {
          studio_id: authUser.studioId,
          ...parsed.data,
          updated_at: new Date().toISOString(),
        },
        { onConflict: 'studio_id' },
      )
      .select('*')
      .single()

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'waitlist rules upsert failed')
      return NextResponse.json({ error: 'Failed to save rules' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.id,
      'waitlist_auto_promote_rules.upsert',
      { type: 'marketing_waitlist_rules', id: authUser.studioId },
      { auto_promote_on_cancel: parsed.data.auto_promote_on_cancel },
      authUser.studioId,
    )

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'waitlist rules PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/marketing/waitlist/list
 *
 * Returns waitlist_entries for the current studio with optional filters.
 * Joined with client, artist, service data.
 *
 * Query params:
 *   artist_id  — filter by artist
 *   service_id — filter by service
 *   event_id   — filter by flash_event (note: waitlist_entries doesn't yet have
 *               a flash_event_id column — returns empty if provided; TODO: M6 migration)
 *   status     — filter by status
 *   page       — 1-based page number (default 1)
 *   per_page   — items per page (default 50, max 100)
 */
export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const artistId = searchParams.get('artist_id')
  const serviceId = searchParams.get('service_id')
  const status = searchParams.get('status')
  const page = Math.max(1, parseInt(searchParams.get('page') ?? '1', 10))
  const perPage = Math.min(100, Math.max(1, parseInt(searchParams.get('per_page') ?? '50', 10)))
  const offset = (page - 1) * perPage

  try {
    const supabase = await createClient()

    let query = supabase
      .from('waitlist_entries')
      .select(
        `
        id,
        status,
        created_at,
        offered_at,
        offered_expires_at,
        offered_booking_id,
        notes,
        preferred_dates,
        preferred_days_of_week,
        client:clients(id, first_name, last_name, email, phone),
        artist:artists(id, display_name, avatar_url),
        service:services(id, name, duration_min, color)
      `,
        { count: 'exact' },
      )
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: false })
      .range(offset, offset + perPage - 1)

    if (artistId) query = query.eq('artist_id', artistId)
    if (serviceId) query = query.eq('service_id', serviceId)
    if (status) query = query.eq('status', status)

    const { data, count, error } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'waitlist list fetch failed')
      return NextResponse.json({ error: 'Failed to fetch waitlist' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
      page,
      per_page: perPage,
      total_pages: Math.ceil((count ?? 0) / perPage),
    })
  } catch (err) {
    logger.error({ err }, 'waitlist list GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState, useRef, useEffect } from 'react'
import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import { ChevronDown } from 'lucide-react'
import { cn } from '@/lib/utils'

export type WaitlistStatus = 'active' | 'offered' | 'expired' | 'cancelled' | 'booked'

interface FilterOption {
  id: string
  name: string
}

interface WaitlistFilterPillsProps {
  artists: FilterOption[]
  services: FilterOption[]
  events: FilterOption[]
  /** URL-driven current values */
  currentArtistId?: string
  currentServiceId?: string
  currentEventId?: string
  currentStatus?: WaitlistStatus
}

const STATUS_OPTIONS: { value: WaitlistStatus; label: string }[] = [
  { value: 'active', label: 'Active' },
  { value: 'offered', label: 'Offered' },
  { value: 'booked', label: 'Booked' },
  { value: 'expired', label: 'Expired' },
  { value: 'cancelled', label: 'Cancelled' },
]

/**
 * URL-driven filter pills for the Waitlist tab.
 * Selected state = Onyx bg + bone text. Unselected = outline.
 * Dropdowns are native-friendly popovers for accessibility.
 */
export function WaitlistFilterPills({
  artists,
  services,
  events,
  currentArtistId,
  currentServiceId,
  currentEventId,
  currentStatus,
}: WaitlistFilterPillsProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  function setFilter(key: string, value: string | null) {
    const params = new URLSearchParams(searchParams.toString())
    if (value) {
      params.set(key, value)
      // Clear conflicting filters when switching pill type
      if (key === 'w_artist') { params.delete('w_service'); params.delete('w_event') }
      if (key === 'w_service') { params.delete('w_artist'); params.delete('w_event') }
      if (key === 'w_event') { params.delete('w_artist'); params.delete('w_service') }
    } else {
      params.delete(key)
    }
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  function clearAll() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('w_artist')
    params.delete('w_service')
    params.delete('w_event')
    params.delete('w_status')
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  const isFiltered = !!(currentArtistId || currentServiceId || currentEventId || currentStatus)
  const isAllActive = !isFiltered

  return (
    <div
      className="flex flex-wrap items-center gap-2"
      role="group"
      aria-label="Waitlist filters"
    >
      {/* All */}
      <Pill
        label="All"
        active={isAllActive}
        onClick={clearAll}
        aria-label="Show all waitlist entries"
      />

      {/* Per artist */}
      <DropdownPill
        label="Artist"
        options={artists}
        selectedId={currentArtistId}
        onSelect={(id) => setFilter('w_artist', id)}
        onClear={() => setFilter('w_artist', null)}
        aria-label="Filter by artist"
      />

      {/* Per service */}
      <DropdownPill
        label="Service"
        options={services}
        selectedId={currentServiceId}
        onSelect={(id) => setFilter('w_service', id)}
        onClear={() => setFilter('w_service', null)}
        aria-label="Filter by service"
      />

      {/* Per flash event */}
      {events.length > 0 && (
        <DropdownPill
          label="Flash event"
          options={events}
          selectedId={currentEventId}
          onSelect={(id) => setFilter('w_event', id)}
          onClear={() => setFilter('w_event', null)}
          aria-label="Filter by flash event"
        />
      )}

      {/* By status */}
      <DropdownPill
        label="Status"
        options={STATUS_OPTIONS.map((s) => ({ id: s.value, name: s.label }))}
        selectedId={currentStatus}
        onSelect={(id) => setFilter('w_status', id)}
        onClear={() => setFilter('w_status', null)}
        aria-label="Filter by status"
      />
    </div>
  )
}

// ── Internal pill atom ────────────────────────────────────────────────────────

interface PillProps {
  label: string
  active: boolean
  onClick: () => void
  'aria-label'?: string
}

function Pill({ label, active, onClick, 'aria-label': ariaLabel }: PillProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={ariaLabel ?? label}
      aria-pressed={active}
      className={cn(
        'inline-flex h-7 items-center rounded-full border px-3 text-xs font-medium transition-colors',
        active
          ? 'border-[color:var(--color-onyx)] bg-[color:var(--color-onyx)] text-[color:var(--color-bone)]'
          : 'border-[color:var(--color-border)] bg-transparent text-[color:var(--color-onyx)] hover:border-[color:var(--color-onyx)]',
      )}
    >
      {label}
    </button>
  )
}

// ── Dropdown pill ─────────────────────────────────────────────────────────────

interface DropdownPillProps {
  label: string
  options: FilterOption[]
  selectedId?: string
  onSelect: (id: string) => void
  onClear: () => void
  'aria-label'?: string
}

function DropdownPill({
  label,
  options,
  selectedId,
  onSelect,
  onClear,
  'aria-label': ariaLabel,
}: DropdownPillProps) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)
  const selectedOption = options.find((o) => o.id === selectedId)
  const isActive = !!selectedId

  // Close on outside click
  useEffect(() => {
    function onPointerDown(e: PointerEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    if (open) {
      document.addEventListener('pointerdown', onPointerDown)
      return () => document.removeEventListener('pointerdown', onPointerDown)
    }
  }, [open])

  // Close on Escape
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') setOpen(false)
    }
    if (open) {
      document.addEventListener('keydown', onKey)
      return () => document.removeEventListener('keydown', onKey)
    }
  }, [open])

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        aria-label={ariaLabel ?? label}
        aria-expanded={open}
        aria-haspopup="listbox"
        onClick={() => setOpen((o) => !o)}
        className={cn(
          'inline-flex h-7 items-center gap-1 rounded-full border px-3 text-xs font-medium transition-colors',
          isActive
            ? 'border-[color:var(--color-onyx)] bg-[color:var(--color-onyx)] text-[color:var(--color-bone)]'
            : 'border-[color:var(--color-border)] bg-transparent text-[color:var(--color-onyx)] hover:border-[color:var(--color-onyx)]',
        )}
      >
        {isActive ? selectedOption?.name ?? label : label}
        <ChevronDown
          className={cn('h-3 w-3 shrink-0 transition-transform', open && 'rotate-180')}
          aria-hidden
        />
      </button>

      {open && (
        <div
          role="listbox"
          aria-label={`${label} options`}
          className="absolute top-full z-20 mt-1 min-w-[10rem] rounded-lg border border-[color:var(--color-border)] bg-[color:var(--color-bone)] py-1 shadow-lift"
        >
          {isActive && (
            <button
              type="button"
              role="option"
              aria-selected={false}
              onClick={() => { onClear(); setOpen(false) }}
              className="w-full px-3 py-1.5 text-left text-xs text-[color:var(--color-stone)] hover:bg-[color:var(--color-border)]/20"
            >
              Clear filter
            </button>
          )}
          {options.map((opt) => (
            <button
              key={opt.id}
              type="button"
              role="option"
              aria-selected={opt.id === selectedId}
              onClick={() => { onSelect(opt.id); setOpen(false) }}
              className={cn(
                'w-full px-3 py-1.5 text-left text-xs transition-colors',
                opt.id === selectedId
                  ? 'font-medium text-[color:var(--color-onyx)]'
                  : 'text-[color:var(--color-onyx)] hover:bg-[color:var(--color-border)]/20',
              )}
            >
              {opt.name}
            </button>
          ))}
          {options.length === 0 && (
            <p className="px-3 py-2 text-xs text-[color:var(--color-stone)]">None available</p>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Mail } from 'lucide-react'
import type { WaitlistStatus } from './WaitlistFilterPills'

interface WaitlistFilter {
  artistId?: string
  serviceId?: string
  eventId?: string
  status?: WaitlistStatus
  /** Resolved client IDs from the filtered waitlist (passed in from WaitlistList) */
  clientIds?: string[]
}

interface MessageWaitlistButtonProps {
  filter: WaitlistFilter
  /** Count of entries in the filtered set (for accessibility label) */
  count: number
}

/**
 * Opens the campaign drawer with a transient audience filter representing
 * the current waitlist filter set.
 *
 * Encodes the filter as a base64 JSON payload in the URL:
 *   ?campaign=new&waitlist_filter=<base64>
 *
 * CampaignDrawer parses this and translates to a client_ids audience filter.
 */
export function MessageWaitlistButton({ filter, count }: MessageWaitlistButtonProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  function openDrawer() {
    const params = new URLSearchParams(searchParams.toString())
    params.set('campaign', 'new')

    // Encode filter as base64 JSON for the drawer to parse
    const encoded = btoa(JSON.stringify(filter))
    params.set('waitlist_filter', encoded)

    router.push(`${pathname}?${params.toString()}`, { scroll: false })
  }

  const label = count > 0
    ? `Message ${count.toLocaleString()} waitlist ${count === 1 ? 'member' : 'members'}`
    : 'Message the waitlist'

  return (
    <Button
      type="button"
      variant="default"
      size="sm"
      className="h-8 gap-1.5 text-xs"
      onClick={openDrawer}
      disabled={count === 0}
      aria-label={label}
    >
      <Mail className="h-3.5 w-3.5 shrink-0" aria-hidden />
      Message the list
    </Button>
  )
}
